```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS n, min(time) AS t0, max(time) AS t1, min(value) AS vmin, max(value) AS vmax FROM abnormal_metrics WHERE metric IN ('k8s.container.restarts','k8s.container.ready') AND attr_k8s_pod_name LIKE 'geo-%' GROUP BY 1,2 ORDER BY 2",
          "claim": "geo pod restarted repeatedly (counter 2 to 6) and its container ready flag stayed at 0 during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS n, avg(duration)/1e6 AS avg_ms, max(attr_status_code) AS st FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1",
          "claim": "From 01:56 on, search's calls to geo return Error status in about 0.02 ms, versus about 0.5 ms normally."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) AS err_share FROM abnormal_traces WHERE service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server' GROUP BY 1 ORDER BY 1",
          "claim": "search Server spans for search.Search/Nearby are almost all Error from 01:56 onward, after geo calls start failing."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code AS code, attr_status_code AS st, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2,3 ORDER BY 2",
          "claim": "frontend HTTP /hotels returns 500 with Error status for 461 of 463 requests in the incident window; normally all return 200."
        }
      ]
    }
  ]
}
```

